function findGaps(arr) {
  const gaps = [];
  for (let i = 1; i < arr.length; i++) {
    if (arr[i] - arr[i-1] > 1) {
      gaps.push([arr[i-1] + 1, arr[i] - 1]);
    }
  }
  return gaps;
}
